// UnmarshallXMLToStage unmarshals an XML document into stage (and its sub-stages),
// staging all reachable instances and assigning deterministic Gong Names.
func UnmarshallXMLToStage(stage *Stage, xmlBytes []byte) error {
	utf8Bytes := ensureUTF8XML(xmlBytes)
	rootElementName := detectRootXMLElementLocalName(utf8Bytes)

	switch rootElementName {
	case "REQ-IF":
		var rootObj REQ_IF
		if err := xml.Unmarshal(utf8Bytes, &rootObj); err != nil {
			return fmt.Errorf("xml unmarshal into REQ_IF failed: %w", err)
		}
		stage.StageBranch(&rootObj)
		propagateCrossStageBranches(stage)
		enforceInstanceNames(stage)
		return nil
	default:
		var rootObj REQ_IF
		if err := xml.Unmarshal(utf8Bytes, &rootObj); err != nil {
			return fmt.Errorf("xml unmarshal into REQ_IF failed: %w", err)
		}
		stage.StageBranch(&rootObj)
		propagateCrossStageBranches(stage)
		enforceInstanceNames(stage)
		return nil
	}
}

// MarshallStageToXML serializes the staged root XML element back to indented XML bytes.
func MarshallStageToXML(stage *Stage) ([]byte, error) {
	if insts := stage.GetInstancesSorted[*REQ_IF](); len(insts) > 0 {
		out, err := xml.MarshalIndent(insts[0], "", "  ")
		if err != nil {
			return nil, err
		}
		return append([]byte(xml.Header), out...), nil
	}
	return nil, fmt.Errorf("no root XML element instance is currently staged")
}

func detectRootXMLElementLocalName(data []byte) string {
	dec := xml.NewDecoder(bytes.NewReader(data))
	for {
		tok, err := dec.Token()
		if err != nil {
			if err == io.EOF {
				break
			}
			return ""
		}
		if se, ok := tok.(xml.StartElement); ok {
			return se.Name.Local
		}
	}
	return ""
}

func ensureUTF8XML(data []byte) []byte {
	if len(data) >= 2 {
		// Check UTF-16 LE BOM (FF FE) or UTF-16 BE BOM (FE FF)
		if data[0] == 0xFF && data[1] == 0xFE {
			u16s := make([]uint16, (len(data)-2)/2)
			for i := range u16s {
				u16s[i] = uint16(data[2+2*i]) | (uint16(data[2+2*i+1]) << 8)
			}
			runes := utf16.Decode(u16s)
			out := string(runes)
			out = strings.Replace(out, "encoding=\"UTF-16\"", "encoding=\"UTF-8\"", 1)
			out = strings.Replace(out, "encoding='UTF-16'", "encoding='UTF-8'", 1)
			return []byte(out)
		}
		if data[0] == 0xFE && data[1] == 0xFF {
			u16s := make([]uint16, (len(data)-2)/2)
			for i := range u16s {
				u16s[i] = (uint16(data[2+2*i]) << 8) | uint16(data[2+2*i+1])
			}
			runes := utf16.Decode(u16s)
			out := string(runes)
			out = strings.Replace(out, "encoding=\"UTF-16\"", "encoding=\"UTF-8\"", 1)
			out = strings.Replace(out, "encoding='UTF-16'", "encoding='UTF-8'", 1)
			return []byte(out)
		}
	}
	return data
}

type goFileUploadCallback struct {
	stager *Stager
}

func (cb *goFileUploadCallback) OnFileUpload(loadedFile *load.FileToUpload) error {
	decodedBytes, err := base64.StdEncoding.DecodeString(loadedFile.Base64EncodedContent)
	if err != nil {
		log.Printf("Failed decoding base64 Go file: %v", err)
		return err
	}

	cb.stager.stage.Reset()
	if err := cb.stager.stage.ParseAstString(string(decodedBytes), true); err != nil {
		log.Printf("Failed parsing Multi-Stage Go AST: %v", err)
		return err
	}

	ext := filepath.Ext(loadedFile.Name)
	cb.stager.fileName = strings.TrimSuffix(loadedFile.Name, ext)
	cb.stager.stage.Commit()
	return nil
}

type xmlFileUploadCallback struct {
	stager *Stager
}

func (cb *xmlFileUploadCallback) OnFileUpload(loadedFile *load.FileToUpload) error {
	decodedBytes, err := base64.StdEncoding.DecodeString(loadedFile.Base64EncodedContent)
	if err != nil {
		log.Printf("Failed decoding base64 XML file: %v", err)
		return err
	}

	cb.stager.stage.Reset()
	if err := UnmarshallXMLToStage(cb.stager.stage, decodedBytes); err != nil {
		log.Printf("Failed unmarshalling XML file: %v", err)
		return err
	}

	ext := filepath.Ext(loadedFile.Name)
	cb.stager.fileName = strings.TrimSuffix(loadedFile.Name, ext)
	cb.stager.stage.Commit()
	return nil
}

func (stager *Stager) ux_load() {
	stager.loadStageGo.Reset()
	fileToUploadGo := (&load.FileToUpload{
		Name:              "fileGo",
		FileToUploadProxy: &goFileUploadCallback{stager: stager},
	}).Stage(stager.loadStageGo)
	_ = fileToUploadGo
	(&load.Message{
		Name: "Drop Multi-Stage .go file here",
	}).Stage(stager.loadStageGo)
	stager.loadStageGo.Commit()

	stager.loadStageXML.Reset()
	fileToUploadXML := (&load.FileToUpload{
		Name:              "fileXML",
		FileToUploadProxy: &xmlFileUploadCallback{stager: stager},
	}).Stage(stager.loadStageXML)
	_ = fileToUploadXML
	(&load.Message{
		Name: "Drop .xml file here",
	}).Stage(stager.loadStageXML)
	stager.loadStageXML.Commit()
}

func (stager *Stager) exportGoFile() {
	log.Println("Button: Export MultiStage as Go file")
	stager.loadStageGo.Reset()

	stager.stage.ComputeReferenceAndOrders()
	data, err := stager.stage.MarshallToString("", "main")
	if err != nil {
		log.Printf("Error marshalling MultiStage to Go string: %v", err)
		return
	}

	baseName := stager.fileName
	if baseName == "" {
		baseName = "stage"
	}
	encoded := base64.StdEncoding.EncodeToString([]byte(data))
	(&load.FileToDownload{
		Name:                 baseName + ".go",
		Base64EncodedContent: encoded,
	}).Stage(stager.loadStageGo)

	stager.loadStageGo.Commit()
}

func (stager *Stager) exportXMLFile() {
	log.Println("Button: Export XML")
	stager.loadStageXML.Reset()

	xmlBytes, err := MarshallStageToXML(stager.stage)
	if err != nil {
		log.Printf("Error marshalling Stage to XML: %v", err)
		return
	}

	baseName := stager.fileName
	if baseName == "" {
		baseName = "document"
	}
	encoded := base64.StdEncoding.EncodeToString(xmlBytes)
	(&load.FileToDownload{
		Name:                 baseName + ".xml",
		Base64EncodedContent: encoded,
	}).Stage(stager.loadStageXML)

	stager.loadStageXML.Commit()
}

func (stager *Stager) ux_button() {
	stager.buttonStage.Reset()

	layout := new(button.Layout).Stage(stager.buttonStage)
	group1 := new(button.Group).Stage(stager.buttonStage)
	group1.Percentage = 100
	layout.Groups = append(layout.Groups, group1)

	btnExportGo := (&button.Button{
		Name:        "Export MultiStage as Go file",
		Icon:        string(tree_buttons.BUTTON_fact_check),
		Label:       "Export MultiStage as Go file",
		HasToolTip:  true,
		ToolTipText: "Serialize all packages/stages to a single deterministic Go file",
		OnClick: func() {
			stager.exportGoFile()
		},
	}).Stage(stager.buttonStage)

	btnExportXML := (&button.Button{
		Name:        "Export XML",
		Icon:        string(tree_buttons.BUTTON_code),
		Label:       "Export XML",
		HasToolTip:  true,
		ToolTipText: "Serialize the root document element to an XML file",
		OnClick: func() {
			stager.exportXMLFile()
		},
	}).Stage(stager.buttonStage)

	group1.Buttons = append(group1.Buttons, btnExportGo, btnExportXML)

	stager.buttonStage.Commit()
}
